const LIVE_PATH =
	"M580.337 75V35.1H586.607V69.3H596.924V75H580.337ZM602.211 75V35.1H608.481V75H602.211ZM619.846 75L613.804 35.1H620.131L624.235 66.051H624.349L628.453 35.1H634.21L628.168 75H619.846ZM639.501 75V35.1H656.601V40.8H645.771V51.345H654.378V57.045H645.771V69.3H656.601V75H639.501Z";

/** The mark's gradient. Each instance gets its own id, so two logos on one page never share a gradient. */
function MarkGradient({ id }: { id: string }) {
	return (
		<defs>
			<linearGradient id={id} x1="88.1893" y1="22.1134" x2="16.8182" y2="95.2989" gradientUnits="userSpaceOnUse">
				{MARK_STOPS.map((stop) => (
					<stop key={stop.offset} offset={stop.offset} stopColor={stop.color} />
				))}
			</linearGradient>
		</defs>
	);
}

type LogoProps = React.ComponentProps<"svg">;

/**
 * The intercept wordmark with its mark and the boxed "LIVE" tag, as in the expanded Sidebar.
 *
 * Figma: [intercept.ds › Logo](https://www.figma.com/design/dl8m89yfeRZ5uMXnEvdgpY/intercept.ds?node-id=1001-82)
 */
function Logo({ className, ...props }: LogoProps) {
	const gradientId = React.useId();

	return (
		<svg
			data-slot='logo'
			viewBox="0 0 743 120"
			fill="none"
			xmlns="http://www.w3.org/2000/svg"
			role="img"
			aria-label="Intercept Live"
			className={cn("h-[31px] w-auto shrink-0", className)}
			{...props}
		>
			<path d={MARK_PATH} fill={`url(#${gradientId})`} />
			<g className="fill-foreground">
				{/* Figma thickens "intercept" and "LIVE" with a 1px outside stroke. A centered 2px stroke over the fill draws the
				    same outer edge. */}
				<path d={WORDMARK_PATH} className="stroke-foreground" strokeWidth={2} />
				<path d={LIVE_PATH} className="stroke-foreground" strokeWidth={2} />
			</g>
			<rect x={566.5} y={23.5} width={103} height={63} className="stroke-foreground" strokeWidth={7} />
			<MarkGradient id={gradientId} />
		</svg>
	);
}

type LogoSymbolProps = React.ComponentProps<"svg">;

/**
 * The intercept mark on its own, as in the collapsed Sidebar.
 *
 * Figma: [intercept.ds › Logo Symbol](https://www.figma.com/design/dl8m89yfeRZ5uMXnEvdgpY/intercept.ds?node-id=1001-1172)
 */
function LogoSymbol({ className, ...props }: LogoSymbolProps) {
	const gradientId = React.useId();

	return (
		<svg
			data-slot='logo-symbol'
			viewBox="0 0 104 120"
			fill="none"
			xmlns="http://www.w3.org/2000/svg"
			role="img"
			aria-label="Intercept"
			className={cn("h-[31px] w-auto shrink-0", className)}
			{...props}
		>
			<path d={MARK_PATH} fill={`url(#${gradientId})`} />
			<MarkGradient id={gradientId} />
		</svg>
	);
}

export { Logo, LogoSymbol, type LogoProps, type LogoSymbolProps };
